// app/services/newsService.ts
// Cached reads of the per-position news files generated by the nfl-data repo.

import AsyncStorage from '@react-native-async-storage/async-storage';
import { createCache, MINUTE } from './cache';
import type { NewsItem } from './newsDiversity';

const NEWS_BASE_URL = 'https://raw.githubusercontent.com/NityaGehlot/nfl-data/main/data/news';
const cache = createCache({ storage: AsyncStorage, prefix: 'ffh_news_cache_v1:' });

export const TEAM_NEWS_FILES = ['qb', 'rb', 'wr', 'te', 'k'];

export async function getNewsFile(fileKey: string): Promise<NewsItem[]> {
  return cache.get(`news:${fileKey}`, 30 * MINUTE, async () => {
    const res = await fetch(`${NEWS_BASE_URL}/news_${fileKey}.json`);
    if (!res.ok) throw new Error(`Failed to load news_${fileKey}.json`);
    const data = await res.json();
    return Array.isArray(data) ? data : [];
  });
}

// All articles from several position files (missing files are skipped).
export async function getNewsFiles(fileKeys: string[]): Promise<NewsItem[]> {
  const results = await Promise.allSettled([...new Set(fileKeys)].map(getNewsFile));
  return results.flatMap(r => (r.status === 'fulfilled' ? r.value : []));
}

// Seasons available in nfl-data/data/Stats. Uses GitHub's API, which allows only 60
// unauthenticated requests per hour, so the list is cached for a day.
export async function getAvailableStatSeasons(): Promise<number[]> {
  return cache.get('statSeasons', 24 * 60 * MINUTE, async () => {
    const resp = await fetch('https://api.github.com/repos/NityaGehlot/nfl-data/contents/data/Stats');
    if (!resp.ok) throw new Error('Failed to list repo contents');
    const items = await resp.json();
    if (!Array.isArray(items)) return [];
    return items
      .map((it: any) => String(it.name || '').match(/^(\d{4})\s+Season$/))
      .filter(Boolean)
      .map((m: any) => Number(m[1]))
      .sort((a: number, b: number) => b - a);
  }, { persist: true });
}

// When nfl-data's news job last finished (data/news/news_meta.json), or null if unknown.
export async function getNewsUpdatedAt(): Promise<string | null> {
  try {
    const meta = await cache.get('news:meta', 10 * MINUTE, async () => {
      const res = await fetch(`${NEWS_BASE_URL}/news_meta.json`);
      if (!res.ok) throw new Error('no news meta');
      return res.json();
    });
    return typeof meta?.generated_at === 'string' ? meta.generated_at : null;
  } catch {
    return null;
  }
}
